module.exports = [
{ e: "🚁", art: { b: "🚁", s: ["🌀", "🏥", "⛰️", "🆘"], c: ["#4E1B0B", "#E0602C"] },
pt: { h: "Um helicóptero passou bem baixinho, fazendo “tac-tac-tac”, e ficou parado no ar em cima do hospital. “Ele está flutuando!”, gritou Leo. “Avião não consegue fazer isso”, disse o vovô. “O helicóptero tem asas que giram, e isso muda tudo.”", t: "O helicóptero", f: "As pás de cima do helicóptero, o rotor, são asas compridas girando muito rápido. Por isso o helicóptero consegue subir em linha reta, ficar parado no ar e até voar de lado ou de ré. O primeiro helicóptero prático, com o formato que conhecemos, voou em 1939, criado por Igor Sikorsky.", x: "Sem a pequena hélice da cauda, o corpo do helicóptero começaria a girar para o lado contrário do rotor, como um pião!", s: ["Helicópteros conseguem pousar em lugares sem pista, como topos de prédios, montanhas e navios.", "Eles salvam muitas vidas em resgates e levando pacientes para hospitais.", "O desenho do “parafuso aéreo” de Leonardo da Vinci, de 500 anos atrás, já lembrava um helicóptero."], ex: { t: "Helicóptero de palito", m: "um palito de churrasco sem ponta, cartolina, cola quente ou fita (com um adulto)", p: ["Recorte uma tira de cartolina de uns 3 x 15 cm e torça levemente as duas pontas em sentidos opostos, como uma hélice.", "Com um adulto, prenda o meio da tira na ponta do palito.", "Gire o palito rápido entre as palmas das mãos e solte: ele sobe girando! É assim que o rotor empurra o ar para baixo."] }, at: "Missão de resgate", m: "papel, lápis de cor", p: ["Desenhe um helicóptero resgatando alguém numa montanha, no mar ou num prédio.", "Desenhe um heliponto, com o grande H no meio.", "Conte a história do resgate para a família e carimbe a caderneta."], q: "Se você pilotasse um helicóptero, que tipo de missão gostaria de fazer?" },
en: { h: "A helicopter flew very low, going “thwack-thwack-thwack,” and hovered in midair above the hospital. “It's floating!” Leo shouted. “Airplanes can't do that,” Grandpa said. “A helicopter has spinning wings, and that changes everything.”", t: "The helicopter", f: "The blades on top of a helicopter, the rotor, are long wings spinning very fast. That's why a helicopter can go straight up, stay still in the air and even fly sideways or backward. The first practical helicopter with the shape we know flew in 1939, created by Igor Sikorsky.", x: "Without the small propeller on its tail, the helicopter's body would start spinning the opposite way from the rotor, like a top!", s: ["Helicopters can land where there's no runway, like rooftops, mountains and ships.", "They save many lives in rescues and by carrying patients to hospitals.", "Leonardo da Vinci's “aerial screw” drawing from 500 years ago already looked like a helicopter."], ex: { t: "Stick helicopter", m: "a blunt bamboo skewer, poster board, hot glue or tape (with a grown-up)", p: ["Cut a strip of poster board about 3 x 15 cm (1 x 6 inches) and twist the two ends slightly in opposite directions, like a propeller.", "With a grown-up, attach the middle of the strip to the tip of the skewer.", "Spin the skewer fast between your palms and let go: it rises while spinning! That's how a rotor pushes air down."] }, at: "Rescue mission", m: "paper, colored pencils", p: ["Draw a helicopter rescuing someone on a mountain, at sea or on a building.", "Draw a helipad with the big H in the middle.", "Tell your family the rescue story and stamp your logbook."], q: "If you flew a helicopter, what kind of mission would you like to do?" },
es: { h: "Un helicóptero pasó bien bajito, haciendo “tac-tac-tac”, y se quedó quieto en el aire sobre el hospital. “¡Está flotando!”, gritó Leo. “Un avión no puede hacer eso”, dijo el abuelo. “El helicóptero tiene alas que giran, y eso lo cambia todo.”", t: "El helicóptero", f: "Las palas de arriba del helicóptero, el rotor, son alas largas que giran muy rápido. Por eso el helicóptero puede subir en línea recta, quedarse quieto en el aire y hasta volar de costado o hacia atrás. El primer helicóptero práctico, con la forma que conocemos, voló en 1939, creado por Igor Sikorsky.", x: "¡Sin la pequeña hélice de la cola, el cuerpo del helicóptero empezaría a girar hacia el lado contrario del rotor, como un trompo!", s: ["Los helicópteros pueden aterrizar en lugares sin pista, como techos de edificios, montañas y barcos.", "Salvan muchas vidas en rescates y llevando pacientes a hospitales.", "El dibujo del “tornillo aéreo” de Leonardo da Vinci, de hace 500 años, ya se parecía a un helicóptero."], ex: { t: "Helicóptero de palito", m: "un palito de brochette sin punta, cartulina, pegamento caliente o cinta (con un adulto)", p: ["Recorta una tira de cartulina de unos 3 x 15 cm y tuerce un poco las dos puntas en sentidos opuestos, como una hélice.", "Con un adulto, pega el medio de la tira en la punta del palito.", "Haz girar el palito rápido entre las palmas y suéltalo: ¡sube girando! Así empuja el rotor el aire hacia abajo."] }, at: "Misión de rescate", m: "papel, lápices de colores", p: ["Dibuja un helicóptero rescatando a alguien en una montaña, en el mar o en un edificio.", "Dibuja un helipuerto, con la gran H en el medio.", "Cuéntale la historia del rescate a tu familia y sella la libreta."], q: "Si pilotearas un helicóptero, ¿qué tipo de misión te gustaría hacer?" } },

{ e: "🌊", art: { b: "🛥️", s: ["🌊", "🔥", "💧", "🛩️"], c: ["#0B3A5A", "#2CA0C2"] },
pt: { h: "Na praia, Nina e Leo viram um avião pousar na água, bem devagar, levantando espuma. “Avião que é barco?”, riu Leo. O vovô contou que existem aviões com boias no lugar das rodas, e até aviões que enchem a barriga de água para apagar incêndios na floresta.", t: "Aviões da água", f: "Hidroaviões são aviões que pousam e decolam na água, usando boias ou um casco parecido com o de um barco. Alguns são usados para combater incêndios: eles deslizam sobre um lago, enchem tanques enormes de água em segundos e voam para jogá-la sobre o fogo.", x: "Em 1927, o hidroavião brasileiro Jahú atravessou o Oceano Atlântico comandado pelo aviador brasileiro João Ribeiro de Barros!", s: ["Alguns aviões de combate a incêndio conseguem recolher uns 6 mil litros de água em cerca de 12 segundos.", "Hidroaviões são muito úteis em lugares com muitos rios e lagos, como a Amazônia e o Canadá.", "O avião original Jahú está guardado num museu no estado de São Paulo."], ex: { t: "Afunda ou flutua?", m: "uma bacia com água, duas bolinhas iguais de massinha", p: ["Jogue uma bolinha de massinha na água: ela afunda.", "Com a outra, faça um barquinho achatado, com as bordas levantadas, e coloque na água.", "Ela flutua! O mesmo material, com outro formato, empurra mais água e boia. As boias dos hidroaviões funcionam assim."] }, at: "Avião bombeiro", m: "papel, lápis de cor", p: ["Desenhe um avião bombeiro passando sobre um lago e enchendo a barriga de água.", "Depois desenhe ele jogando a água sobre uma floresta em chamas.", "Escreva três dicas para evitar incêndios na natureza e carimbe a caderneta."], q: "Por que você acha que é tão importante proteger as florestas do fogo?" },
en: { h: "At the beach, Nina and Leo saw a plane land on the water very slowly, kicking up spray. “A plane that's a boat?” Leo laughed. Grandpa told them some planes have floats instead of wheels, and some even fill their bellies with water to put out forest fires.", t: "Water planes", f: "Seaplanes are airplanes that land and take off on water, using floats or a boat-like hull. Some are used to fight fires: they skim across a lake, fill huge tanks with water in seconds and fly off to drop it on the flames.", x: "In 1927, the Brazilian seaplane Jahú crossed the Atlantic Ocean, commanded by Brazilian aviator João Ribeiro de Barros!", s: ["Some firefighting planes can scoop up about 6,000 liters (1,600 gallons) of water in around 12 seconds.", "Seaplanes are very useful in places with lots of rivers and lakes, like the Amazon and Canada.", "The original Jahú plane is kept in a museum in the state of São Paulo."], ex: { t: "Sink or float?", m: "a basin of water, two equal balls of play dough", p: ["Drop one ball of play dough in the water: it sinks.", "Shape the other into a flat little boat with raised edges and set it on the water.", "It floats! The same material in a different shape pushes aside more water and stays up. Seaplane floats work like that."] }, at: "Firefighting plane", m: "paper, colored pencils", p: ["Draw a firefighting plane skimming over a lake and filling its belly with water.", "Then draw it dropping the water on a burning forest.", "Write three tips for preventing wildfires and stamp your logbook."], q: "Why do you think it's so important to protect forests from fire?" },
es: { h: "En la playa, Nina y Leo vieron un avión aterrizar en el agua, bien despacio, levantando espuma. “¿Un avión que es barco?”, se rió Leo. El abuelo les contó que hay aviones con flotadores en lugar de ruedas, y hasta aviones que llenan la panza de agua para apagar incendios en el bosque.", t: "Aviones del agua", f: "Los hidroaviones son aviones que aterrizan y despegan en el agua, usando flotadores o un casco parecido al de un barco. Algunos se usan para combatir incendios: se deslizan sobre un lago, llenan tanques enormes de agua en segundos y vuelan para soltarla sobre el fuego.", x: "¡En 1927, el hidroavión brasileño Jahú cruzó el océano Atlántico al mando del aviador brasileño João Ribeiro de Barros!", s: ["Algunos aviones contra incendios pueden cargar unos 6.000 litros de agua en unos 12 segundos.", "Los hidroaviones son muy útiles en lugares con muchos ríos y lagos, como la Amazonía y Canadá.", "El avión original Jahú está guardado en un museo del estado de São Paulo."], ex: { t: "¿Se hunde o flota?", m: "una palangana con agua, dos bolitas iguales de plastilina", p: ["Tira una bolita de plastilina al agua: se hunde.", "Con la otra, haz un barquito chato con los bordes levantados y ponlo en el agua.", "¡Flota! El mismo material, con otra forma, empuja más agua y flota. Los flotadores de los hidroaviones funcionan así."] }, at: "Avión bombero", m: "papel, lápices de colores", p: ["Dibuja un avión bombero pasando sobre un lago y llenándose la panza de agua.", "Después dibújalo soltando el agua sobre un bosque en llamas.", "Escribe tres consejos para evitar incendios en la naturaleza y sella la libreta."], q: "¿Por qué crees que es tan importante proteger los bosques del fuego?" } },

{ e: "📦", art: { b: "📦", s: ["✉️", "🚑", "💊", "🌍"], c: ["#3A2A0B", "#C2902C"] },
pt: { h: "A campainha tocou, e era uma encomenda que tinha vindo de outro país em apenas dois dias. “Como chegou tão rápido?”, perguntou Nina. “De avião!”, respondeu o vovô. “Os aviões não carregam só gente. Eles levam cartas, remédios, comida e até órgãos para transplante.”", t: "Aviões que ajudam", f: "Muitos aviões trabalham carregando coisas: os aviões de carga levam encomendas, alimentos frescos, flores e remédios pelo mundo. Os aviões-ambulância transportam pacientes, e aviões levam vacinas e ajuda a lugares atingidos por desastres.", x: "O primeiro voo oficial de correio aéreo do mundo aconteceu em 1911, na Índia, levando cerca de 6 mil cartas por uns 10 quilômetros!", s: ["Um órgão para transplante, como um coração, precisa chegar rápido ao paciente, e por isso muitas vezes viaja de avião.", "Durante a pandemia de covid-19, aviões de carga levaram bilhões de doses de vacina pelo mundo.", "Muitos aviões de passageiros também levam carga na parte de baixo, junto com as malas."], ex: { t: "A água que não cai do canudo", m: "um canudo, um copo com água", p: ["Mergulhe o canudo na água e tampe a ponta de cima com o dedo.", "Levante o canudo com o dedo tampando: a água fica presa lá dentro!", "Tire o dedo e a água cai. A pressão do ar segura a água, e os aviões de incêndio e de carga também usam muito o ar e a pressão a seu favor."] }, at: "Pacote voador", m: "uma caixinha, papel, lápis de cor, fita", p: ["Escolha alguém que mora longe e prepare um pacotinho com um desenho ou cartinha.", "Faça uma etiqueta de carga aérea com o endereço, o voo e o selo “frágil”.", "Se der, mande pelo correio de verdade! Carimbe a caderneta."], q: "Se você pudesse mandar um presente de avião para qualquer pessoa, para quem seria?" },
en: { h: "The doorbell rang, and it was a package that had come from another country in just two days. “How did it get here so fast?” Nina asked. “By plane!” Grandpa answered. “Planes don't just carry people. They carry letters, medicines, food and even organs for transplants.”", t: "Planes that help", f: "Many planes work carrying things: cargo planes fly packages, fresh food, flowers and medicine around the world. Air ambulances carry patients, and planes bring vaccines and aid to places hit by disasters.", x: "The world's first official airmail flight happened in 1911 in India, carrying about 6,000 letters for about 10 kilometers (6 miles)!", s: ["An organ for transplant, like a heart, has to reach the patient quickly, so it often travels by plane.", "During the COVID-19 pandemic, cargo planes carried billions of vaccine doses around the world.", "Many passenger planes also carry cargo underneath, along with the suitcases."], ex: { t: "Water that stays in the straw", m: "a straw, a glass of water", p: ["Dip the straw into the water and cover the top end with your finger.", "Lift the straw out with your finger still on top: the water stays trapped inside!", "Remove your finger and the water falls out. Air pressure holds the water, and airplanes use air and pressure to their advantage too."] }, at: "Flying package", m: "a small box, paper, colored pencils, tape", p: ["Choose someone who lives far away and make a little package with a drawing or note.", "Make an air cargo label with the address, flight and a “fragile” sticker.", "If you can, really mail it! Stamp your logbook."], q: "If you could send a gift by plane to anyone, who would it be?" },
es: { h: "Sonó el timbre, y era un paquete que había llegado de otro país en solo dos días. “¿Cómo llegó tan rápido?”, preguntó Nina. “¡En avión!”, respondió el abuelo. “Los aviones no llevan solo gente. Llevan cartas, remedios, comida y hasta órganos para trasplantes.”", t: "Aviones que ayudan", f: "Muchos aviones trabajan transportando cosas: los aviones de carga llevan paquetes, alimentos frescos, flores y medicamentos por el mundo. Los aviones ambulancia trasladan pacientes, y los aviones llevan vacunas y ayuda a lugares afectados por desastres.", x: "¡El primer vuelo oficial de correo aéreo del mundo fue en 1911, en la India, y llevó unas 6.000 cartas a lo largo de unos 10 kilómetros!", s: ["Un órgano para trasplante, como un corazón, tiene que llegar rápido al paciente, por eso muchas veces viaja en avión.", "Durante la pandemia de covid-19, aviones de carga llevaron miles de millones de dosis de vacunas por el mundo.", "Muchos aviones de pasajeros también llevan carga en la parte de abajo, junto con las maletas."], ex: { t: "El agua que no se cae de la pajita", m: "una pajita, un vaso con agua", p: ["Mete la pajita en el agua y tapa la punta de arriba con el dedo.", "Saca la pajita con el dedo tapando: ¡el agua queda atrapada adentro!", "Quita el dedo y el agua cae. La presión del aire sostiene el agua, y los aviones también usan mucho el aire y la presión a su favor."] }, at: "Paquete volador", m: "una cajita, papel, lápices de colores, cinta", p: ["Elige a alguien que vive lejos y prepara un paquetito con un dibujo o una cartita.", "Haz una etiqueta de carga aérea con la dirección, el vuelo y el sello “frágil”.", "¡Si puedes, mándalo por correo de verdad! Sella la libreta."], q: "Si pudieras mandar un regalo en avión a cualquier persona, ¿a quién se lo mandarías?" } },

{ e: "🏭", art: { b: "🏭", s: ["✈️", "🔧", "🎓", "🌎"], c: ["#0B3A4E", "#2C7AA0"] },
pt: { h: "No aeroporto, Leo leu um nome no avião e perguntou de onde ele vinha. “Esse foi feito no Brasil!”, disse o vovô, orgulhoso. Nina não sabia que o Brasil fabricava aviões. “Fabrica, e são vendidos para o mundo inteiro”, completou ele.", t: "Aviões feitos no Brasil", f: "A Embraer é uma fabricante brasileira de aviões, criada em 1969 em São José dos Campos, em São Paulo. Ela começou fazendo um pequeno avião chamado Bandeirante e hoje é uma das maiores fabricantes de jatos comerciais do mundo.", x: "Aviões brasileiros voam por companhias aéreas de dezenas de países, de vários continentes!", s: ["Perto da fábrica fica o ITA, uma escola de engenharia aeronáutica criada em 1950, que forma muitos engenheiros de aviões.", "A Embraer também faz aviões executivos, aviões militares e aviões agrícolas.", "Para criar um avião novo, engenheiros testam modelos em túneis de vento e em computadores por anos."], ex: { t: "Túnel de vento caseiro", m: "um ventilador (com um adulto), um avião de papel, linha, fita", p: ["Prenda o avião de papel pelo meio com uma linha e segure a linha na frente do ventilador ligado no mínimo.", "Observe como o avião se mexe: ele fica reto ou balança?", "Mude as dobras das asas e teste de novo. Os engenheiros fazem isso com modelos de verdade antes de construir um avião!"] }, at: "Projeto de avião", m: "papel quadriculado, régua, lápis de cor", p: ["Desenhe o projeto de um avião brasileiro inventado por você, visto de cima e de lado.", "Escolha nome, cores e quantos passageiros ele leva.", "Apresente o projeto como se fosse um engenheiro e carimbe a caderneta."], q: "Você gostaria de trabalhar construindo aviões? Que parte faria?" },
en: { h: "At the airport, Leo read a name on a plane and asked where it came from. “That one was made in Brazil!” Grandpa said proudly. Nina didn't know Brazil built airplanes. “It does, and they're sold all over the world,” he added.", t: "Airplanes made in Brazil", f: "Embraer is a Brazilian airplane maker founded in 1969 in São José dos Campos, São Paulo. It started by building a small plane called the Bandeirante, and today it's one of the largest makers of commercial jets in the world.", x: "Brazilian-made planes fly for airlines in dozens of countries across several continents!", s: ["Near the factory is ITA, an aeronautical engineering school founded in 1950 that trains many airplane engineers.", "Embraer also makes business jets, military planes and crop-dusting planes.", "To create a new plane, engineers test models in wind tunnels and on computers for years."], ex: { t: "Homemade wind tunnel", m: "a fan (with a grown-up), a paper airplane, thread, tape", p: ["Tie a thread around the middle of the paper airplane and hold it in front of the fan on its lowest setting.", "Watch how the plane moves: does it stay steady or wobble?", "Change the wing folds and test again. Engineers do this with real models before building an airplane!"] }, at: "Airplane design", m: "graph paper, ruler, colored pencils", p: ["Draw the design of a Brazilian airplane you invent, seen from above and from the side.", "Choose its name, colors and how many passengers it carries.", "Present your design like an engineer and stamp your logbook."], q: "Would you like to work building airplanes? Which part would you do?" },
es: { h: "En el aeropuerto, Leo leyó un nombre en un avión y preguntó de dónde venía. “¡Ese se hizo en Brasil!”, dijo el abuelo, orgulloso. Nina no sabía que Brasil fabricaba aviones. “Sí, y se venden en todo el mundo”, agregó él.", t: "Aviones hechos en Brasil", f: "Embraer es una fabricante brasileña de aviones, creada en 1969 en São José dos Campos, São Paulo. Empezó haciendo un pequeño avión llamado Bandeirante y hoy es uno de los mayores fabricantes de aviones comerciales a reacción del mundo.", x: "¡Aviones hechos en Brasil vuelan para aerolíneas de decenas de países, en varios continentes!", s: ["Cerca de la fábrica está el ITA, una escuela de ingeniería aeronáutica creada en 1950, que forma a muchos ingenieros de aviones.", "Embraer también hace aviones ejecutivos, aviones militares y aviones agrícolas.", "Para crear un avión nuevo, los ingenieros prueban modelos en túneles de viento y en computadoras durante años."], ex: { t: "Túnel de viento casero", m: "un ventilador (con un adulto), un avión de papel, hilo, cinta", p: ["Ata un hilo en el medio del avión de papel y sostén el hilo frente al ventilador encendido en la velocidad mínima.", "Observa cómo se mueve el avión: ¿se queda derecho o se balancea?", "Cambia los pliegues de las alas y prueba otra vez. ¡Los ingenieros hacen esto con modelos de verdad antes de construir un avión!"] }, at: "Proyecto de avión", m: "papel cuadriculado, regla, lápices de colores", p: ["Dibuja el proyecto de un avión inventado por ti, visto desde arriba y de costado.", "Elige nombre, colores y cuántos pasajeros lleva.", "Presenta el proyecto como un ingeniero y sella la libreta."], q: "¿Te gustaría trabajar construyendo aviones? ¿Qué parte harías?" } },

{ e: "🦺", art: { b: "🦺", s: ["📦", "🟧", "🛟", "✅"], c: ["#5A2A0B", "#E0802C"] },
pt: { h: "Leo perguntou, meio preocupado, se avião era perigoso. O vovô respondeu com calma: “O avião é um dos jeitos mais seguros de viajar que existem. E sabe por quê? Porque cada detalhe é conferido muitas vezes, e cada problema que já aconteceu serviu para deixar todos os outros voos mais seguros.”", t: "Segurança e a caixa-preta", f: "Antes de cada voo, mecânicos e pilotos fazem listas de verificação e conferem tudo. Os aviões têm sistemas duplicados: se um falha, outro funciona. E todo avião grande carrega a “caixa-preta”, que grava tudo o que acontece no voo.", x: "A caixa-preta, na verdade, é laranja! A cor forte ajuda a encontrá-la. Ela aguenta pancadas enormes, fogo e até ficar no fundo do mar, onde solta um sinal para ser achada.", s: ["Na verdade são duas caixas: uma grava os dados do voo e a outra grava as conversas na cabine.", "Os aviões grandes conseguem continuar voando com um motor só, se o outro parar.", "As comissárias e os comissários de bordo são treinados para cuidar da segurança, não só para servir lanche."], ex: { t: "Ovo protegido", m: "um ovo cru, um saquinho plástico com fecho, materiais macios (algodão, papel amassado, esponja), uma caixinha, um adulto", p: ["Coloque o ovo dentro do saquinho fechado, para não sujar nada se quebrar.", "Monte uma “caixa-preta” na caixinha, enchendo bem de material macio em volta do ovo.", "Com um adulto, solte a caixa de uma altura de uns 2 metros e abra: o ovo sobreviveu? Teste outros materiais!"] }, at: "Checklist do piloto", m: "papel, lápis", p: ["Pilotos usam listas de verificação. Faça uma checklist para sair de casa: escova de dentes, mochila, lanche…", "Use a lista de manhã e marque cada item conferido.", "Carimbe a caderneta com o carimbo de “voo seguro”."], q: "Que listas você poderia usar para não esquecer nada no seu dia?" },
en: { h: "Leo asked, a little worried, whether airplanes were dangerous. Grandpa answered calmly: “Flying is one of the safest ways to travel there is. And do you know why? Because every detail is checked many times, and every problem that ever happened was used to make all the other flights safer.”", t: "Safety and the black box", f: "Before every flight, mechanics and pilots go through checklists and inspect everything. Planes have backup systems: if one fails, another works. And every big plane carries a “black box” that records everything that happens on the flight.", x: "The black box is actually orange! The bright color helps people find it. It can survive huge impacts, fire and even sitting at the bottom of the sea, where it sends out a signal so it can be found.", s: ["There are really two boxes: one records flight data and the other records the conversations in the cockpit.", "Big planes can keep flying on just one engine if the other one stops.", "Flight attendants are trained to keep everyone safe, not just to serve snacks."], ex: { t: "Protected egg", m: "a raw egg, a zip-top plastic bag, soft materials (cotton, crumpled paper, sponge), a small box, a grown-up", p: ["Put the egg inside the sealed bag so nothing gets messy if it breaks.", "Build a “black box” in the small box, packing soft material all around the egg.", "With a grown-up, drop the box from about 2 meters (6 feet) and open it: did the egg survive? Test other materials!"] }, at: "Pilot's checklist", m: "paper, pencil", p: ["Pilots use checklists. Make a checklist for leaving the house: toothbrush, backpack, snack…", "Use the list in the morning and check off each item.", "Stamp your logbook with a “safe flight” stamp."], q: "What checklists could you use so you don't forget anything during your day?" },
es: { h: "Leo preguntó, un poco preocupado, si el avión era peligroso. El abuelo respondió con calma: “El avión es una de las formas más seguras de viajar que existen. ¿Y saben por qué? Porque cada detalle se revisa muchas veces, y cada problema que ocurrió sirvió para que todos los demás vuelos fueran más seguros.”", t: "La seguridad y la caja negra", f: "Antes de cada vuelo, mecánicos y pilotos repasan listas de verificación y revisan todo. Los aviones tienen sistemas duplicados: si uno falla, otro funciona. Y todo avión grande lleva la “caja negra”, que graba todo lo que pasa en el vuelo.", x: "¡La caja negra, en realidad, es naranja! El color fuerte ayuda a encontrarla. Aguanta golpes enormes, fuego y hasta quedarse en el fondo del mar, donde emite una señal para que la encuentren.", s: ["En realidad son dos cajas: una graba los datos del vuelo y la otra graba las conversaciones en la cabina.", "Los aviones grandes pueden seguir volando con un solo motor si el otro se detiene.", "Las azafatas y los auxiliares de vuelo están entrenados para cuidar la seguridad, no solo para servir la merienda."], ex: { t: "Huevo protegido", m: "un huevo crudo, una bolsita de plástico con cierre, materiales blandos (algodón, papel arrugado, esponja), una cajita, un adulto", p: ["Pon el huevo dentro de la bolsita cerrada, para no ensuciar nada si se rompe.", "Arma una “caja negra” en la cajita, rellenando bien con material blando alrededor del huevo.", "Con un adulto, suelta la caja desde unos 2 metros de altura y ábrela: ¿sobrevivió el huevo? ¡Prueba otros materiales!"] }, at: "Lista del piloto", m: "papel, lápiz", p: ["Los pilotos usan listas de verificación. Haz una lista para salir de casa: cepillo de dientes, mochila, merienda…", "Usa la lista a la mañana y marca cada cosa revisada.", "Sella la libreta con el sello de “vuelo seguro”."], q: "¿Qué listas podrías usar para no olvidarte de nada en tu día?" } },

{ e: "☀️", art: { b: "☀️", s: ["🔋", "🌱", "✈️", "🍃"], c: ["#4E4A0B", "#C2B02C"] },
pt: { h: "Nina leu que os aviões gastam muito combustível e soltam fumaça que esquenta o planeta. Ficou preocupada. O vovô mostrou a foto de um avião enorme, coberto de painéis solares, que deu a volta ao mundo sem uma gota de combustível. “Muita gente está trabalhando para mudar isso”, disse.", t: "Aviões e o planeta", f: "A maioria dos aviões usa querosene de aviação, um combustível que solta gases que aquecem o planeta. Por isso, cientistas estão criando combustíveis feitos de plantas e até de óleo de cozinha usado, além de aviões elétricos pequenos e projetos com hidrogênio.", x: "O avião solar Solar Impulse 2 deu a volta ao mundo entre 2015 e 2016 usando só a energia do Sol! Suas asas eram mais largas que as de um Boeing 747, mas ele pesava quase o mesmo que um carro.", s: ["Os aviões novos gastam bem menos combustível por passageiro do que os aviões antigos.", "Já existem pequenos aviões totalmente elétricos voando em treinamento e em viagens curtas.", "Escolher o trem ou o ônibus para viagens curtas também ajuda o planeta."], ex: { t: "Calor do Sol", m: "dois cubos de gelo, um papel preto e um papel branco, um lugar ao sol", p: ["Coloque o papel preto e o branco lado a lado, no sol.", "Ponha um cubo de gelo em cima de cada um.", "Qual derrete primeiro? O preto absorve mais energia do Sol! Os painéis solares também são escuros para captar bastante luz."] }, at: "Avião do futuro verde", m: "papel, lápis de cor", p: ["Desenhe um avião que não polui: pode ter painéis solares, baterias ou uma ideia inventada por você.", "Escreva como ele consegue energia.", "Escreva uma dica para economizar energia em casa e carimbe a caderneta."], q: "O que a sua família pode fazer para cuidar do planeta?" },
en: { h: "Nina read that airplanes burn lots of fuel and give off gases that warm the planet. She got worried. Grandpa showed her a photo of a huge plane covered in solar panels that flew around the world without a drop of fuel. “Lots of people are working to change this,” he said.", t: "Airplanes and the planet", f: "Most airplanes use jet fuel, a kerosene that releases gases that warm the planet. That's why scientists are creating fuels made from plants and even used cooking oil, as well as small electric planes and hydrogen projects.", x: "The solar airplane Solar Impulse 2 flew around the world in 2015 and 2016 using only the Sun's energy! Its wings were wider than a Boeing 747's, but it weighed about as much as a car.", s: ["New planes burn much less fuel per passenger than old ones.", "There are already small all-electric planes flying for training and short trips.", "Choosing a train or bus for short trips also helps the planet."], ex: { t: "Heat from the Sun", m: "two ice cubes, a sheet of black paper and a sheet of white paper, a sunny spot", p: ["Put the black and white paper side by side in the sun.", "Place an ice cube on each.", "Which melts first? Black absorbs more of the Sun's energy! Solar panels are dark to capture lots of light too."] }, at: "Green plane of the future", m: "paper, colored pencils", p: ["Draw a plane that doesn't pollute: it could have solar panels, batteries or an idea you invent.", "Write how it gets its energy.", "Write a tip for saving energy at home and stamp your logbook."], q: "What can your family do to take care of the planet?" },
es: { h: "Nina leyó que los aviones gastan mucho combustible y largan gases que calientan el planeta. Se preocupó. El abuelo le mostró la foto de un avión enorme, cubierto de paneles solares, que dio la vuelta al mundo sin una gota de combustible. “Mucha gente está trabajando para cambiar esto”, dijo.", t: "Los aviones y el planeta", f: "La mayoría de los aviones usa queroseno de aviación, un combustible que larga gases que calientan el planeta. Por eso, científicos están creando combustibles hechos de plantas y hasta de aceite de cocina usado, además de aviones eléctricos pequeños y proyectos con hidrógeno.", x: "¡El avión solar Solar Impulse 2 dio la vuelta al mundo entre 2015 y 2016 usando solo la energía del Sol! Sus alas eran más anchas que las de un Boeing 747, pero pesaba casi lo mismo que un auto.", s: ["Los aviones nuevos gastan mucho menos combustible por pasajero que los antiguos.", "Ya existen pequeños aviones totalmente eléctricos que vuelan en entrenamientos y viajes cortos.", "Elegir el tren o el autobús para viajes cortos también ayuda al planeta."], ex: { t: "El calor del Sol", m: "dos cubitos de hielo, un papel negro y un papel blanco, un lugar al sol", p: ["Pon el papel negro y el blanco uno al lado del otro, al sol.", "Coloca un cubito de hielo encima de cada uno.", "¿Cuál se derrite primero? ¡El negro absorbe más energía del Sol! Los paneles solares también son oscuros para captar mucha luz."] }, at: "Avión verde del futuro", m: "papel, lápices de colores", p: ["Dibuja un avión que no contamina: puede tener paneles solares, baterías o una idea inventada por ti.", "Escribe cómo consigue su energía.", "Escribe un consejo para ahorrar energía en casa y sella la libreta."], q: "¿Qué puede hacer tu familia para cuidar el planeta?" } },

{ e: "🛸", art: { b: "🛸", s: ["🌀", "📷", "🌾", "📦"], c: ["#1B1B3A", "#5A5AA0"] },
pt: { h: "No parque, um drone zumbia lá no alto, tirando fotos. Leo ficou fascinado com as quatro hélices pequenininhas. “Como ele sabe para onde ir?”, perguntou. “Um computadorzinho dentro dele muda a velocidade de cada hélice o tempo todo”, explicou o vovô.", t: "Os drones", f: "Drones são aeronaves sem piloto a bordo, controladas por controle remoto ou por computador. Muitos têm quatro hélices: duas giram num sentido e duas no outro. Mudando a velocidade de cada uma, o drone sobe, desce, vira e anda para qualquer lado.", x: "Em Ruanda, na África, drones entregam sangue e remédios para hospitais em lugares difíceis de chegar desde 2016!", s: ["Drones são usados para fotografar, vigiar plantações, procurar pessoas perdidas e inspecionar pontes.", "Para voar com drones, é preciso seguir regras de segurança, como não voar perto de aeroportos.", "Alguns drones são do tamanho de uma mão, e outros são grandes como aviões."], ex: { t: "Equilíbrio da régua", m: "uma régua, moedas iguais, o seu dedo", p: ["Equilibre a régua no dedo, bem no meio.", "Coloque uma moeda numa ponta: ela cai para esse lado. Coloque outra na ponta oposta: equilibra de novo!", "Agora tente equilibrar com 2 moedas de um lado e 1 do outro, mudando o dedo de lugar. O drone faz isso o tempo todo com as hélices!"] }, at: "Missão do drone", m: "papel, lápis de cor", p: ["Invente uma missão para um drone que ajude a sua cidade.", "Desenhe o drone e o caminho que ele faria, visto de cima.", "Escreva uma regra de segurança para drones e carimbe a caderneta."], q: "Que trabalho você daria para um drone fazer na sua casa?" },
en: { h: "At the park, a drone buzzed high above, taking pictures. Leo was fascinated by its four tiny propellers. “How does it know where to go?” he asked. “A little computer inside keeps changing the speed of each propeller all the time,” Grandpa explained.", t: "Drones", f: "Drones are aircraft with no pilot on board, flown by remote control or by computer. Many have four propellers: two spin one way and two the other. By changing each one's speed, the drone goes up, down, turns and moves in any direction.", x: "In Rwanda, in Africa, drones have been delivering blood and medicine to hospitals in hard-to-reach places since 2016!", s: ["Drones are used to take photos, watch over crops, search for lost people and inspect bridges.", "Flying a drone means following safety rules, like not flying near airports.", "Some drones fit in your hand, and others are as big as airplanes."], ex: { t: "Ruler balance", m: "a ruler, identical coins, your finger", p: ["Balance the ruler on your finger, right in the middle.", "Put a coin on one end: it tips that way. Put another on the opposite end: it balances again!", "Now try balancing 2 coins on one side and 1 on the other by moving your finger. A drone does this all the time with its propellers!"] }, at: "Drone mission", m: "paper, colored pencils", p: ["Invent a mission for a drone that helps your town.", "Draw the drone and the route it would take, seen from above.", "Write a drone safety rule and stamp your logbook."], q: "What job would you give a drone at your house?" },
es: { h: "En la plaza, un dron zumbaba allá arriba, sacando fotos. Leo quedó fascinado con las cuatro hélices chiquititas. “¿Cómo sabe adónde ir?”, preguntó. “Una computadorita adentro cambia la velocidad de cada hélice todo el tiempo”, explicó el abuelo.", t: "Los drones", f: "Los drones son aeronaves sin piloto a bordo, controladas a distancia o por computadora. Muchos tienen cuatro hélices: dos giran en un sentido y dos en el otro. Cambiando la velocidad de cada una, el dron sube, baja, gira y se mueve hacia cualquier lado.", x: "¡En Ruanda, en África, desde 2016 hay drones que llevan sangre y medicamentos a hospitales en lugares difíciles de alcanzar!", s: ["Los drones se usan para sacar fotos, vigilar cultivos, buscar personas perdidas e inspeccionar puentes.", "Para volar drones hay que seguir reglas de seguridad, como no volar cerca de aeropuertos.", "Algunos drones caben en una mano y otros son grandes como aviones."], ex: { t: "Equilibrio de la regla", m: "una regla, monedas iguales, tu dedo", p: ["Equilibra la regla en tu dedo, justo en el medio.", "Pon una moneda en una punta: se cae hacia ese lado. Pon otra en la punta opuesta: ¡se equilibra otra vez!", "Ahora intenta equilibrar 2 monedas de un lado y 1 del otro moviendo el dedo. ¡El dron hace eso todo el tiempo con sus hélices!"] }, at: "Misión del dron", m: "papel, lápices de colores", p: ["Inventa una misión para un dron que ayude a tu ciudad.", "Dibuja el dron y el camino que haría, visto desde arriba.", "Escribe una regla de seguridad para drones y sella la libreta."], q: "¿Qué trabajo le darías a un dron en tu casa?" } },

{ e: "🦅", art: { b: "🦅", s: ["🪶", "🐦", "🦆", "✈️"], c: ["#2A3A1B", "#6A8A4A"] },
pt: { h: "Um bando de patos passou voando em forma de V, e o Pipoca ficou olhando da janela, de boca aberta. “Por que eles voam assim?”, perguntou Nina. “Para economizar energia”, respondeu o vovô. “Os pássaros ainda são os melhores professores dos engenheiros de aviões.”", t: "Aprendendo com os pássaros", f: "Os engenheiros continuam copiando ideias dos pássaros. As pontinhas viradas para cima nas asas de muitos aviões, chamadas winglets, lembram as penas das pontas das asas das aves e ajudam a gastar menos combustível.", x: "O andorinhão-preto pode ficar voando sem pousar por até 10 meses seguidos: ele come, bebe e até dorme no ar!", s: ["Os pássaros que voam em V aproveitam o ar empurrado para cima pelo vizinho da frente, e se revezam na liderança.", "O albatroz-errante pode ter asas de mais de 3 metros e planar por horas quase sem bater as asas.", "O beija-flor é o único pássaro que consegue voar de ré de verdade."], ex: { t: "Pena à prova d'água", m: "uma pena (de travesseiro ou de artesanato), um conta-gotas ou canudo, água, uma gotinha de detergente", p: ["Pingue algumas gotas de água sobre a pena e observe: elas escorregam em bolinhas.", "Agora misture uma gotinha de detergente na água e pingue de novo.", "A água encharca a pena! Os pássaros têm um óleo natural que protege as penas. Por isso derramamentos de petróleo e produtos de limpeza fazem tão mal a eles."] }, at: "Esquadrilha em V", m: "papel, lápis de cor", p: ["Desenhe uma esquadrilha de pássaros em V e, ao lado, uma esquadrilha de aviões.", "Desenhe winglets nas asas dos aviões, iguais às pontas das asas dos pássaros.", "Pesquise com um adulto qual pássaro do Brasil voa mais alto ou mais longe e carimbe a caderneta."], q: "Que outra ideia dos animais você acha que poderia virar uma invenção?" },
en: { h: "A flock of ducks flew past in a V shape, and Popcorn watched from the window with his mouth open. “Why do they fly like that?” Nina asked. “To save energy,” Grandpa answered. “Birds are still the best teachers airplane engineers have.”", t: "Learning from birds", f: "Engineers keep borrowing ideas from birds. The turned-up tips on many airplane wings, called winglets, are like the feathers at the tips of birds' wings and help planes burn less fuel.", x: "The common swift can stay in the air without landing for up to 10 months: it eats, drinks and even sleeps while flying!", s: ["Birds flying in a V ride on air pushed upward by the bird ahead, and they take turns leading.", "The wandering albatross can have wings more than 3 meters (10 feet) across and glide for hours, barely flapping.", "The hummingbird is the only bird that can truly fly backward."], ex: { t: "Waterproof feather", m: "a feather (from a pillow or craft store), a dropper or straw, water, a tiny drop of dish soap", p: ["Drip a few drops of water onto the feather and watch: they roll off in little balls.", "Now mix a tiny drop of dish soap into the water and drip again.", "The water soaks the feather! Birds have a natural oil that protects their feathers. That's why oil spills and cleaning chemicals are so harmful to them."] }, at: "V formation", m: "paper, colored pencils", p: ["Draw a flock of birds in a V and, next to it, a formation of airplanes.", "Draw winglets on the planes' wings, like the tips of bird wings.", "With a grown-up, find out which bird flies highest or farthest, and stamp your logbook."], q: "What other idea from animals do you think could become an invention?" },
es: { h: "Una bandada de patos pasó volando en forma de V, y Palomita miró desde la ventana con la boca abierta. “¿Por qué vuelan así?”, preguntó Nina. “Para ahorrar energía”, respondió el abuelo. “Los pájaros siguen siendo los mejores maestros de los ingenieros de aviones.”", t: "Aprendiendo de los pájaros", f: "Los ingenieros siguen copiando ideas de los pájaros. Las puntitas dobladas hacia arriba en las alas de muchos aviones, llamadas winglets, se parecen a las plumas de las puntas de las alas de las aves y ayudan a gastar menos combustible.", x: "¡El vencejo común puede quedarse volando sin aterrizar hasta 10 meses seguidos: come, bebe y hasta duerme en el aire!", s: ["Los pájaros que vuelan en V aprovechan el aire que empuja hacia arriba el de adelante, y se turnan para ir primero.", "El albatros viajero puede tener alas de más de 3 metros y planear durante horas casi sin aletear.", "El colibrí es el único pájaro que puede volar hacia atrás de verdad."], ex: { t: "Pluma impermeable", m: "una pluma (de almohada o de librería), un gotero o pajita, agua, una gotita de detergente", p: ["Echa unas gotas de agua sobre la pluma y observa: resbalan en bolitas.", "Ahora mezcla una gotita de detergente en el agua y echa otra vez.", "¡El agua empapa la pluma! Los pájaros tienen un aceite natural que protege sus plumas. Por eso los derrames de petróleo y los productos de limpieza les hacen tanto daño."] }, at: "Escuadrilla en V", m: "papel, lápices de colores", p: ["Dibuja una bandada de pájaros en V y, al lado, una escuadrilla de aviones.", "Dibuja winglets en las alas de los aviones, iguales a las puntas de las alas de los pájaros.", "Busca con un adulto qué pájaro vuela más alto o más lejos y sella la libreta."], q: "¿Qué otra idea de los animales crees que podría convertirse en un invento?" } },

{ e: "🔮", art: { b: "🚀", s: ["🛸", "🏙️", "🔋", "🌌"], c: ["#1B0B3A", "#6A2CB0"] },
pt: { h: "Leo desenhou um carro com asas e perguntou se um dia ia existir. “Já estão testando!”, disse o vovô. “Táxis voadores elétricos, que decolam como helicóptero e voam como avião.” Nina imaginou ir para a escola voando por cima do trânsito.", t: "O futuro do voo", f: "Engenheiros estão criando novas máquinas voadoras: táxis aéreos elétricos que decolam e pousam na vertical, aviões movidos a hidrogênio, aviões supersônicos silenciosos e até aviões espaciais que poderiam ir de um continente a outro passando pelo espaço.", x: "Em 1903, o primeiro voo dos Wright durou 12 segundos. Apenas 66 anos depois, pessoas pisaram na Lua! Imagine o que pode acontecer até você ser adulto.", s: ["Os táxis aéreos elétricos são chamados de eVTOL, que em inglês quer dizer “decolagem e pouso vertical elétrico”.", "Empresas do mundo todo, inclusive do Brasil, estão desenvolvendo esses veículos.", "O hidrogênio, quando usado como combustível, solta principalmente vapor de água."], ex: { t: "Hovercraft de CD", m: "um CD velho, uma tampa de garrafa de squeeze (que abre e fecha puxando), cola quente (com um adulto), uma bexiga", p: ["Com um adulto, cole a tampa de squeeze bem em cima do furo do meio do CD, sem deixar vazar ar.", "Encha a bexiga, encaixe a boca dela na tampa fechada e coloque o CD numa mesa lisa.", "Puxe a tampa para abrir: o ar sai por baixo e o CD desliza flutuando sobre uma almofada de ar!"] }, at: "Cidade do futuro", m: "papel grande, lápis de cor", p: ["Desenhe uma cidade daqui a 50 anos, com veículos voadores.", "Desenhe onde eles pousam, onde carregam as baterias e as faixas do céu.", "Escreva qual seria a sua profissão nessa cidade e carimbe a caderneta."], q: "Que meio de transporte você gostaria que existisse no futuro?" },
en: { h: "Leo drew a car with wings and asked if one would ever exist. “They're already testing them!” Grandpa said. “Electric flying taxis that take off like helicopters and fly like airplanes.” Nina imagined flying to school over the traffic.", t: "The future of flight", f: "Engineers are creating new flying machines: electric air taxis that take off and land vertically, hydrogen-powered planes, quiet supersonic jets and even spaceplanes that could go from one continent to another by passing through space.", x: "In 1903, the Wrights' first flight lasted 12 seconds. Just 66 years later, people walked on the Moon! Imagine what might happen by the time you're grown up.", s: ["Electric air taxis are called eVTOLs, which stands for “electric vertical takeoff and landing.”", "Companies around the world, including in Brazil, are developing these vehicles.", "Hydrogen, when used as fuel, gives off mostly water vapor."], ex: { t: "CD hovercraft", m: "an old CD, a pop-up sports bottle cap, hot glue (with a grown-up), a balloon", p: ["With a grown-up, glue the sports cap right over the center hole of the CD so no air leaks.", "Blow up the balloon, fit its neck over the closed cap and set the CD on a smooth table.", "Pull the cap open: air flows out underneath and the CD glides, floating on a cushion of air!"] }, at: "City of the future", m: "large paper, colored pencils", p: ["Draw a city 50 years from now, with flying vehicles.", "Draw where they land, where they charge their batteries and the lanes in the sky.", "Write what your job would be in that city and stamp your logbook."], q: "What kind of transportation would you like to exist in the future?" },
es: { h: "Leo dibujó un auto con alas y preguntó si algún día existiría. “¡Ya los están probando!”, dijo el abuelo. “Taxis voladores eléctricos, que despegan como helicóptero y vuelan como avión.” Nina se imaginó yendo a la escuela volando por encima del tránsito.", t: "El futuro del vuelo", f: "Los ingenieros están creando nuevas máquinas voladoras: taxis aéreos eléctricos que despegan y aterrizan en vertical, aviones a hidrógeno, aviones supersónicos silenciosos y hasta aviones espaciales que podrían ir de un continente a otro pasando por el espacio.", x: "¡En 1903, el primer vuelo de los Wright duró 12 segundos. Solo 66 años después, personas pisaron la Luna! Imagina lo que puede pasar hasta que seas adulto.", s: ["Los taxis aéreos eléctricos se llaman eVTOL, que en inglés quiere decir “despegue y aterrizaje vertical eléctrico”.", "Empresas de todo el mundo, incluso de Brasil, están desarrollando estos vehículos.", "El hidrógeno, cuando se usa como combustible, larga sobre todo vapor de agua."], ex: { t: "Aerodeslizador de CD", m: "un CD viejo, una tapa deportiva de botella (que se abre tirando), pegamento caliente (con un adulto), un globo", p: ["Con un adulto, pega la tapa deportiva justo sobre el agujero del medio del CD, sin que se escape aire.", "Infla el globo, coloca su boca en la tapa cerrada y pon el CD en una mesa lisa.", "Tira de la tapa para abrirla: ¡el aire sale por abajo y el CD se desliza flotando sobre un colchón de aire!"] }, at: "Ciudad del futuro", m: "papel grande, lápices de colores", p: ["Dibuja una ciudad dentro de 50 años, con vehículos voladores.", "Dibuja dónde aterrizan, dónde cargan las baterías y los carriles del cielo.", "Escribe cuál sería tu profesión en esa ciudad y sella la libreta."], q: "¿Qué medio de transporte te gustaría que existiera en el futuro?" } },

{ e: "🎖️", art: { b: "🎖️", s: ["✈️", "⭐", "🛫", "🎉"], c: ["#1B3A6B", "#D4A82C"] },
pt: { h: "Na última noite, a caderneta de voo estava cheia de carimbos. O vovô colocou uma música de cerimônia, e Nina e Leo entraram na sala de quepe. “Pelo poder da Escola de Voo, eu entrego a vocês o brevê de piloto mirim!”, disse ele. O Pipoca ganhou um brevê também, de copiloto.", t: "Formatura na Escola de Voo", f: "Em pouco mais de cem anos, os humanos saíram de voos de 12 segundos para aviões que cruzam o planeta em algumas horas. Isso só foi possível porque muitas pessoas curiosas, de vários países, testaram, erraram, aprenderam e tentaram de novo.", x: "Todos os dias, milhares de aviões estão voando ao mesmo tempo pelo mundo, levando milhões de pessoas!", s: ["Para voar, um avião usa as quatro forças: sustentação, peso, tração e arrasto.", "Inventores como Gusmão, Santos-Dumont, os Wright e muitas pilotas pioneiras abriram caminho no céu.", "O futuro do voo pode ser elétrico, solar e talvez até espacial, e quem sabe você ajude a construí-lo."], ex: { t: "Desafio final do avião de papel", m: "folhas de papel, clipes, tesoura, fita métrica", p: ["Use tudo o que aprendeu: asas largas, peso no lugar certo e abinhas para controle.", "Construa o seu melhor avião de papel e faça 3 lançamentos.", "Meça a distância e o tempo no ar. Depois ajuste e tente bater o seu próprio recorde!"] }, at: "Meu brevê de piloto mirim", m: "cartolina, lápis dourado ou amarelo, fita", p: ["Desenhe e recorte um brevê de asas com seu nome no meio.", "Escreva atrás as três aulas de que mais gostou.", "Faça uma cerimônia de formatura em família e coloque o último carimbo na caderneta!"], q: "De tudo o que você aprendeu sobre aviões, o que mais te surpreendeu?" },
en: { h: "On the last night, the flight logbook was full of stamps. Grandpa played ceremony music, and Nina and Leo marched into the living room wearing their caps. “By the power of the Flight School, I present you with your junior pilot wings!” he said. Popcorn got wings too, as copilot.", t: "Flight School graduation", f: "In just over a hundred years, humans went from 12-second flights to airplanes that cross the planet in a few hours. That was only possible because many curious people from many countries tested, failed, learned and tried again.", x: "Every day, thousands of airplanes are in the air at the same time around the world, carrying millions of people!", s: ["To fly, a plane uses the four forces: lift, weight, thrust and drag.", "Inventors like Gusmão, Santos-Dumont, the Wrights and many pioneering women pilots opened the way in the sky.", "The future of flight may be electric, solar and maybe even spacebound, and who knows, you might help build it."], ex: { t: "Final paper airplane challenge", m: "sheets of paper, paper clips, scissors, a tape measure", p: ["Use everything you've learned: wide wings, weight in the right place and little flaps for control.", "Build your best paper airplane and make 3 throws.", "Measure the distance and the time in the air. Then adjust it and try to beat your own record!"] }, at: "My junior pilot wings", m: "poster board, a gold or yellow pencil, tape", p: ["Draw and cut out a pair of pilot wings with your name in the middle.", "On the back, write the three lessons you liked best.", "Hold a family graduation ceremony and put the last stamp in your logbook!"], q: "Of everything you learned about airplanes, what surprised you most?" },
es: { h: "En la última noche, la libreta de vuelo estaba llena de sellos. El abuelo puso música de ceremonia, y Nina y Leo entraron a la sala con sus gorras. “¡Por el poder de la Escuela de Vuelo, les entrego las alas de piloto junior!”, dijo. Palomita también recibió sus alas, de copiloto.", t: "Graduación en la Escuela de Vuelo", f: "En poco más de cien años, los humanos pasaron de vuelos de 12 segundos a aviones que cruzan el planeta en pocas horas. Eso solo fue posible porque muchas personas curiosas, de muchos países, probaron, se equivocaron, aprendieron y volvieron a intentar.", x: "¡Todos los días, miles de aviones están volando al mismo tiempo por el mundo, llevando a millones de personas!", s: ["Para volar, un avión usa las cuatro fuerzas: sustentación, peso, empuje y resistencia.", "Inventores como Gusmão, Santos-Dumont, los Wright y muchas pilotas pioneras abrieron camino en el cielo.", "El futuro del vuelo puede ser eléctrico, solar y quizás hasta espacial, y quién sabe, tal vez tú ayudes a construirlo."], ex: { t: "Desafío final del avión de papel", m: "hojas de papel, clips, tijera, cinta métrica", p: ["Usa todo lo que aprendiste: alas anchas, peso en el lugar correcto y solapitas para controlar.", "Construye tu mejor avión de papel y haz 3 lanzamientos.", "Mide la distancia y el tiempo en el aire. ¡Después ajústalo e intenta superar tu propio récord!"] }, at: "Mis alas de piloto junior", m: "cartulina, lápiz dorado o amarillo, cinta", p: ["Dibuja y recorta unas alas de piloto con tu nombre en el medio.", "Atrás, escribe las tres clases que más te gustaron.", "¡Hagan una ceremonia de graduación en familia y pon el último sello en la libreta!"], q: "De todo lo que aprendiste sobre aviones, ¿qué fue lo que más te sorprendió?" } },
];
